insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990002','$12$','Nos extremos, $f(2)=4$ e $f(6)=2$, ambos positivos. O gráfico retilíneo delimita um trapézio com bases verticais $4$ e $2$. A distância entre as bases é $6-2=4$. Logo a área é $(4+2)\cdot4/2=12$. A integral $\int_2^6(5-x/2)\,dx$ confirma a alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
