insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990043','40000000-0000-4000-8000-000000990004','Na fórmula por partes, lembre que uma primitiva de $\sin x$ é $-\cos x$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990004','$-x\cos x+\sin x+C$','Separe $u=x$ e $dv=\sin x\,dx$. Então $du=dx$ e $v=-\cos x$. A fórmula fornece $\int x\sin x\,dx=-x\cos x-\int(-\cos x)\,dx$. O termo restante é $+\sin x$, resultando em $-x\cos x+\sin x+C$. Derivar a expressão devolve $x\sin x$, confirmando A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990041','40000000-0000-4000-8000-000000990004','Separe $u=x$ e $dv=\sin x\,dx$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990042','40000000-0000-4000-8000-000000990004','Então $du=dx$ e $v=-\cos x$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990043','40000000-0000-4000-8000-000000990004','A fórmula fornece $\int x\sin x\,dx=-x\cos x-\int(-\cos x)\,dx$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990044','40000000-0000-4000-8000-000000990004','O termo restante é $+\sin x$, resultando em $-x\cos x+\sin x+C$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
