insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990008','A série diverge porque seus termos não tendem a zero.','O termo geral é $a_n=(n+1)/(2n+1)$. Dividindo por $n$, vemos que $a_n\to1/2$. Esse limite não é zero. Pelo teste do termo geral, a série não pode convergir. A opção C registra exatamente essa conclusão.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990081','40000000-0000-4000-8000-000000990008','O termo geral é $a_n=(n+1)/(2n+1)$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
