insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990012','Integração por partes com $u=\ln x$.','O integrando é $x\cdot\ln x$. Derivar $\ln x$ produz $1/x$. Tomamos $u=\ln x$ e $dv=x\,dx$. O termo restante se reduz a uma integral elementar. Assim, B é a técnica indicada.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
