insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990013','$2\ln|x-1|+3\ln|x+2|+C$','Escrevemos $A/(x-1)+B/(x+2)$. Então $5x+1=A(x+2)+B(x-1)$. Em $x=1$, $A=2$; em $x=-2$, $B=3$. Integramos as duas parcelas logarítmicas. A recomposição confirma a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
