insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990015','Sim; $a_{n+1}-a_n>0$.','Temos $a_{n+1}=(n+1)/(n+2)$. A diferença é $(n+1)/(n+2)-n/(n+1)$. Ela simplifica para $1/((n+1)(n+2))$. Esse valor é positivo para $n\ge1$. Logo B está correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990151','40000000-0000-4000-8000-000000990015','Temos $a_{n+1}=(n+1)/(n+2)$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990152','40000000-0000-4000-8000-000000990015','A diferença é $(n+1)/(n+2)-n/(n+1)$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990153','40000000-0000-4000-8000-000000990015','Ela simplifica para $1/((n+1)(n+2))$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990154','40000000-0000-4000-8000-000000990015','Esse valor é positivo para $n\ge1$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
