insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990017','Converge condicionalmente.','$1/\ln n$ é decrescente e tende a zero. O teste alternado garante convergência. Porém $1/\ln n>1/n$ para $n$ grande. A série dos módulos diverge pela harmônica. A convergência é condicional: B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
