insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990018','O integrando não está definido em $x=0$.','Em $x=0$, o denominador é nulo. Logo $1/\sqrt{x}$ não está definida nesse extremo. A definição usa $\lim_{a\to0^+}\int_a^2x^{-1/2}dx$. Não é um intervalo infinito nem falta de primitiva. C identifica a causa.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
