insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990202','40000000-0000-4000-8000-000000990020','Substitua $z=2x$ em cada potência.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990203','40000000-0000-4000-8000-000000990020','O termo cúbico do seno tem sinal negativo.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990020','$2x-4x^3/3+O(x^5)$','Usamos $\sin z=z-z^3/3!+O(z^5)$. Com $z=2x$, o termo linear é $2x$. O cúbico é $-(2x)^3/3!=-8x^3/6$. Isso equivale a $-4x^3/3$. A alternativa A coincide com o termo cúbico simplificado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990201','40000000-0000-4000-8000-000000990020','Usamos $\sin z=z-z^3/3!+O(z^5)$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990202','40000000-0000-4000-8000-000000990020','Com $z=2x$, o termo linear é $2x$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990203','40000000-0000-4000-8000-000000990020','O cúbico é $-(2x)^3/3!=-8x^3/6$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990204','40000000-0000-4000-8000-000000990020','Isso equivale a $-4x^3/3$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990205','40000000-0000-4000-8000-000000990020','A alternativa A coincide com o termo cúbico simplificado.',5) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
