insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990262','40000000-0000-4000-8000-000000990026','Calcule $a_{n+1}/a_n$ antes de tirar o limite.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000990263','40000000-0000-4000-8000-000000990026','Compare o limite encontrado com $1$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990026','Converge pelo teste da razão.','Seja $a_n=n!/n^n$. A razão é $a_{n+1}/a_n=((n+1)!/(n+1)^{n+1})(n^n/n!)$. Ela simplifica para $(n/(n+1))^n$. O limite é $e^{-1}<1$. Pelo teste da razão, a série converge; B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990261','40000000-0000-4000-8000-000000990026','Seja $a_n=n!/n^n$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990262','40000000-0000-4000-8000-000000990026','A razão é $a_{n+1}/a_n=((n+1)!/(n+1)^{n+1})(n^n/n!)$.',2) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990263','40000000-0000-4000-8000-000000990026','Ela simplifica para $(n/(n+1))^n$.',3) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990264','40000000-0000-4000-8000-000000990026','O limite é $e^{-1}<1$.',4) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
