insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990028','$[-1,5]$','O teste da razão produz $|x-2|<3$. O intervalo aberto é $(-1,5)$. Em $x=5$, resulta $\sum1/n^2$. Em $x=-1$, resulta $\sum(-1)^n/n^2$, também absolutamente convergente. Os dois extremos entram: alternativa D.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
