insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000990029','$0$','A série é $\ln(1+u)=u-u^2/2+u^3/3-\cdots$. Com $u=x^2$, surgem $x^2-x^4/2+x^6/3-\cdots$. Todos os expoentes são pares. Não aparece nenhum termo com $x^5$. O coeficiente é zero, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000990291','40000000-0000-4000-8000-000000990029','A série é $\ln(1+u)=u-u^2/2+u^3/3-\cdots$.',1) on conflict (id) do update set question_id=excluded.question_id,content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
