insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992002','$u=3x^2+1$','A expressão composta é $(3x^2+1)^4$. Defina $u=3x^2+1$; então $du=6x\,dx$. A integral se transforma diretamente em $\int u^4du$. As outras propostas não absorvem todo o diferencial do integrando. Logo a substituição funcional é a alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
