insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992032','40000000-0000-4000-8000-000000992003','Aplique a primeira parte do Teorema Fundamental sem derivar $\cos(t^2)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992033','40000000-0000-4000-8000-000000992003','O símbolo $t$ é variável muda e deve ser trocado por $x$ após a derivação.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992003','$\cos(x^2)$','Temos $F(x)=\int_0^x f(t)dt$, com $f(t)=\cos(t^2)$. Como $f$ é contínua, o Teorema Fundamental fornece $F\prime(x)=f(x)$. Substituir a variável muda resulta em $\cos(x^2)$. O fator $2x$ surgiria apenas se o limite fosse $x^2$. Portanto a alternativa C é a única compatível com o limite dado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992031','40000000-0000-4000-8000-000000992003','Temos $F(x)=\int_0^x f(t)dt$, com $f(t)=\cos(t^2)$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
