insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992033','40000000-0000-4000-8000-000000992003','Substituir a variável muda resulta em $\cos(x^2)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992034','40000000-0000-4000-8000-000000992003','O fator $2x$ surgiria apenas se o limite fosse $x^2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
