insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992043','40000000-0000-4000-8000-000000992004','Somamos a constante arbitrária porque a integral é indefinida.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
