insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992005','$15/2$','A série tem primeiro termo $a=5$ e razão $r=1/3$. Como $|1/3|<1$, a soma infinita existe. Neste caso, a expressão fechada é $S=a/(1-r)$. Isso dá $5/(1-1/3)=5/(2/3)=15/2$. A alternativa B preserva corretamente o termo inicial.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992051','40000000-0000-4000-8000-000000992005','A série tem primeiro termo $a=5$ e razão $r=1/3$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992052','40000000-0000-4000-8000-000000992005','Como $|1/3|<1$, a soma infinita existe.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992053','40000000-0000-4000-8000-000000992005','Neste caso, a expressão fechada é $S=a/(1-r)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992054','40000000-0000-4000-8000-000000992005','Isso dá $5/(1-1/3)=5/(2/3)=15/2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992055','40000000-0000-4000-8000-000000992005','A alternativa B preserva corretamente o termo inicial.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
