insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992006','$1$','Escrevemos $\sqrt{n^2+5n}=n\sqrt{1+5/n}$. Dividir por $n$ deixa $\sqrt{1+5/n}$. Quando $n\to\infty$, temos $5/n\to0$. Pela continuidade da raiz, o limite é $\sqrt1=1$. A resposta finita e positiva corresponde à alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
