insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992007','$1/2$','Defina a integral como $\lim_{b\to\infty}\int_2^b x^{-2}dx$. Uma primitiva é $-1/x$. A integral truncada vale $-1/b+1/2$. O limite de $-1/b$ é zero. Logo a integral converge para $1/2$, alternativa C.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
