insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992011','$12$','A altura da região é $3$. A largura horizontal é $5-1=4$. A área do retângulo é $3\cdot4$. Equivalentemente, $\int_1^5 3dx=12$. Logo a alternativa D fornece a área correta.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
