insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992142','40000000-0000-4000-8000-000000992014','A derivada de $\cos x$ introduz um sinal negativo.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992143','40000000-0000-4000-8000-000000992014','Nos extremos, use $\cos(\pi/4)=\sqrt2/2$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992014','$(1/2)\ln2$','Como $\tan x=\sin x/\cos x$, uma primitiva é $-\ln|\cos x|$. No limite superior, obtemos $-\ln(\sqrt2/2)$. No limite inferior, $-\ln1=0$. Como $\sqrt2/2=2^{-1/2}$, o valor é $(1/2)\ln2$. A alternativa B apresenta esse resultado.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992141','40000000-0000-4000-8000-000000992014','Como $\tan x=\sin x/\cos x$, uma primitiva é $-\ln|\cos x|$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
