insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992015','$0$','A sequência é $a_n=1/n^2$. Quando $n$ cresce, $n^2\to\infty$. O recíproco de uma quantidade positiva ilimitada tende a zero. Logo $a_n\to0$. A alternativa B responde ao limite da sequência, sem afirmar nada sobre uma soma.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
