insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992018','$-1$','Defina $\int_0^1\ln xdx=\lim_{a\to0^+}\int_a^1\ln xdx$. Uma primitiva é $x\ln x-x$. No extremo $1$, o valor é $-1$. No extremo móvel, $a\ln a-a\to0$. A diferença tende a $-1$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
