insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992019','$3$','Para $a_n=n(x/3)^n$, a razão de módulos tende a $|x|/3$. O teste da razão exige $|x|/3<1$. Portanto há convergência para $|x|<3$. O número $3$ é a distância do centro aos extremos do intervalo aberto. Assim, o raio é $3$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992191','40000000-0000-4000-8000-000000992019','Para $a_n=n(x/3)^n$, a razão de módulos tende a $|x|/3$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992192','40000000-0000-4000-8000-000000992019','O teste da razão exige $|x|/3<1$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992193','40000000-0000-4000-8000-000000992019','Portanto há convergência para $|x|<3$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992194','40000000-0000-4000-8000-000000992019','O número $3$ é a distância do centro aos extremos do intervalo aberto.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992195','40000000-0000-4000-8000-000000992019','Assim, o raio é $3$, alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
