insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992202','40000000-0000-4000-8000-000000992020','Aqui o incremento em relação a $1$ é $x=0,2$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
