insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992203','40000000-0000-4000-8000-000000992020','O termo quadrático vale $0,04/2=0,02$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992204','40000000-0000-4000-8000-000000992020','Logo $P_2(0,2)=0,2-0,02=0,18$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
