insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992211','40000000-0000-4000-8000-000000992021','Área geométrica exige identificar a curva superior em cada subintervalo.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992212','40000000-0000-4000-8000-000000992021','Compare $x$ e $x^3$ à esquerda e à direita de zero.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
