insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992231','40000000-0000-4000-8000-000000992023','A','$-1/(a+1)^2$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992232','40000000-0000-4000-8000-000000992023','B','$1/(a+1)^2$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992233','40000000-0000-4000-8000-000000992023','C','$-1/(a-1)^2$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992234','40000000-0000-4000-8000-000000992023','D','$-1/(a+1)$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000992023','50000000-0000-4000-8000-000000992231') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992231','40000000-0000-4000-8000-000000992023','Trate o expoente $a$ como constante e use a integral de $x^a$ como função do parâmetro.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992232','40000000-0000-4000-8000-000000992023','A hipótese $a>-1$ é justamente a condição de convergência na origem.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992233','40000000-0000-4000-8000-000000992023','Derivar $1/(a+1)$ em relação a $a$ introduz o fator $\ln x$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992023','$-1/(a+1)^2$','Defina $F(a)=\int_0^1x^a dx$ para $a>-1$. A avaliação direta fornece $F(a)=1/(a+1)$. Diferenciar sob o sinal de integral dá $F\prime(a)=\int_0^1x^a\ln x\,dx$. Por outro lado, $F\prime(a)=-1/(a+1)^2$. Logo $I(a)=-1/(a+1)^2$, coerente com o integrando negativo e com a alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992231','40000000-0000-4000-8000-000000992023','Defina $F(a)=\int_0^1x^a dx$ para $a>-1$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992232','40000000-0000-4000-8000-000000992023','A avaliação direta fornece $F(a)=1/(a+1)$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992233','40000000-0000-4000-8000-000000992023','Diferenciar sob o sinal de integral dá $F\prime(a)=\int_0^1x^a\ln x\,dx$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992234','40000000-0000-4000-8000-000000992023','Por outro lado, $F\prime(a)=-1/(a+1)^2$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
