insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992025','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','hard','published','Calcule $\int_0^{\pi/2}\frac{\sin^5x}{1+\cos^2x}\,dx$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
