insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992252','40000000-0000-4000-8000-000000992025','B','$\pi/2-1$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992253','40000000-0000-4000-8000-000000992025','C','$8/3-\pi$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992254','40000000-0000-4000-8000-000000992025','D','$2\ln2-1$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
