insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992251','40000000-0000-4000-8000-000000992025','A potência ímpar de seno permite reservar um fator para o diferencial.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992252','40000000-0000-4000-8000-000000992025','Após $u=\cos x$, faça divisão polinomial antes de integrar.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992253','40000000-0000-4000-8000-000000992025','A expressão final deve ser positiva; $\pi-8/3$ satisfaz essa verificação.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992025','$\pi-8/3$','Escreva $\sin^5x=\sin x(1-\cos^2x)^2$. Com $u=\cos x$ e ajuste dos limites, a integral vira $\int_0^1(1-u^2)^2/(1+u^2)du$. A divisão fornece $(1-2u^2+u^4)/(1+u^2)=u^2-3+4/(1+u^2)$. Integrando de $0$ a $1$, obtemos $1/3-3+4(\pi/4)=\pi-8/3$. O valor é positivo e menor que $1$, confirmando a alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992251','40000000-0000-4000-8000-000000992025','Escreva $\sin^5x=\sin x(1-\cos^2x)^2$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992252','40000000-0000-4000-8000-000000992025','Com $u=\cos x$ e ajuste dos limites, a integral vira $\int_0^1(1-u^2)^2/(1+u^2)du$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992253','40000000-0000-4000-8000-000000992025','A divisão fornece $(1-2u^2+u^4)/(1+u^2)=u^2-3+4/(1+u^2)$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992254','40000000-0000-4000-8000-000000992025','Integrando de $0$ a $1$, obtemos $1/3-3+4(\pi/4)=\pi-8/3$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992255','40000000-0000-4000-8000-000000992025','O valor é positivo e menor que $1$, confirmando a alternativa A.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992026','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','hard','published','Para quais valores reais de $p$ a integral $\int_0^2|x-1|^{-p}\,dx$ converge?') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
