insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992264','40000000-0000-4000-8000-000000992026','D','$p>0$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
