insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992303','40000000-0000-4000-8000-000000992030','Somando com denominador $720$, obtemos $(120-180+30-1)/720$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
