insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992031','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','hard','published','Para $a>0$, a área entre $y=x^3-ax$ e o eixo $x$, limitada pelas raízes extremas da função, é $8$. Determine $a$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
insert into public.question_taxonomy_tags (question_id,taxonomy_node_id,is_primary) values ('40000000-0000-4000-8000-000000992031','30000000-0000-4000-8000-000000000004',true) on conflict (question_id,taxonomy_node_id) do update set is_primary=true;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992311','40000000-0000-4000-8000-000000992031','A','$2$',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992312','40000000-0000-4000-8000-000000992031','B','$4$',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992313','40000000-0000-4000-8000-000000992031','C','$8$',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_options (id,question_id,label,content_markdown,sort_order) values ('50000000-0000-4000-8000-000000992314','40000000-0000-4000-8000-000000992031','D','$16$',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id,correct_option_id) values ('40000000-0000-4000-8000-000000992031','50000000-0000-4000-8000-000000992312') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992311','40000000-0000-4000-8000-000000992031','As raízes dependem de $a$ e determinam os limites da área.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992312','40000000-0000-4000-8000-000000992031','Use a paridade de $x^3-ax$ para trabalhar apenas no semieixo positivo.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992313','40000000-0000-4000-8000-000000992031','No intervalo entre $0$ e $\sqrt a$, integre $ax-x^3$, que é o módulo da função.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992031','$4$','As raízes são $-\sqrt a$, $0$ e $\sqrt a$. Como o módulo de uma função ímpar é par, a área total vale $2\int_0^{\sqrt a}(ax-x^3)dx$. A integral interna é $[ax^2/2-x^4/4]_0^{\sqrt a}=a^2/4$. Assim, a área total é $a^2/2$; igualá-la a $8$ dá $a^2=16$. Como $a>0$, resulta $a=4$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992311','40000000-0000-4000-8000-000000992031','As raízes são $-\sqrt a$, $0$ e $\sqrt a$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992312','40000000-0000-4000-8000-000000992031','Como o módulo de uma função ímpar é par, a área total vale $2\int_0^{\sqrt a}(ax-x^3)dx$.',2) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992313','40000000-0000-4000-8000-000000992031','A integral interna é $[ax^2/2-x^4/4]_0^{\sqrt a}=a^2/4$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992314','40000000-0000-4000-8000-000000992031','Assim, a área total é $a^2/2$; igualá-la a $8$ dá $a^2=16$.',4) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992315','40000000-0000-4000-8000-000000992031','Como $a>0$, resulta $a=4$, alternativa B.',5) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.questions (id,subject_id,source_id,kind,difficulty,publication_status,statement_markdown) values ('40000000-0000-4000-8000-000000992032','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000009902','multiple_choice','hard','published','Para $p>1$, calcule $J(p)=\int_e^\infty\frac{dx}{x(\ln x)^p}$.') on conflict (id) do update set source_id=excluded.source_id,difficulty=excluded.difficulty,publication_status=excluded.publication_status,statement_markdown=excluded.statement_markdown;
