insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992032','$1/(p-1)$','Com $u=\ln x$ e $du=dx/x$, temos $J(p)=\int_1^\infty u^{-p}du$. Para $p>1$, uma primitiva é $u^{1-p}/(1-p)$. O termo no infinito tende a zero porque $1-p<0$. No limite inferior, a subtração produz $-1/(1-p)=1/(p-1)$. Portanto $J(p)=1/(p-1)$, alternativa A.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
insert into public.question_solution_steps (id,question_id,content_markdown,sort_order) values ('70000000-0000-4000-8000-000000992321','40000000-0000-4000-8000-000000992032','Com $u=\ln x$ e $du=dx/x$, temos $J(p)=\int_1^\infty u^{-p}du$.',1) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
