insert into public.question_hints (id,question_id,content_markdown,sort_order) values ('60000000-0000-4000-8000-000000992333','40000000-0000-4000-8000-000000992033','Nos extremos, use a estimativa central $(2n)!/(n!)^2\sim4^n/\sqrt{\pi n}$.',3) on conflict (id) do update set content_markdown=excluded.content_markdown,sort_order=excluded.sort_order;
insert into public.question_solutions (question_id,final_answer_markdown,explanation_markdown) values ('40000000-0000-4000-8000-000000992033','$(-3,5)$','A razão dos coeficientes tende a $1/4$, então a série converge quando $|x-1|<4$. O intervalo aberto inicial é $(-3,5)$. Em qualquer extremo, o módulo do termo é $4^n(n!)^2/(2n)!$. Pela estimativa binomial central, esse módulo é assintótico a $\sqrt{\pi n}$ e nem sequer tende a zero. Os dois extremos são excluídos, resultando em $(-3,5)$, alternativa B.') on conflict (question_id) do update set final_answer_markdown=excluded.final_answer_markdown,explanation_markdown=excluded.explanation_markdown;
